    case 4:
      if (lookahead == 'u') ADVANCE(24);
      END_STATE();
    case 5:
      ACCEPT_TOKEN(sym_wildcard_pattern);
      END_STATE();
    case 6:
      if (lookahead == 'l') ADVANCE(25);
